<div class="form-group"><label>Nama</label><input class="form-control" name="name" value="{{ old('name', $user->name ?? '') }}" required></div><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" value="{{ old('email', $user->email ?? '') }}" required></div><div class="form-group"><label>Role</label><select class="form-select" name="role" required><option value="staff" @selected(old('role', $user->role ?? 'staff') === 'staff')>Staff</option><option value="admin" @selected(old('role', $user->role ?? '') === 'admin')>Admin</option></select></div><div class="row"><div class="col-md-6"><div class="form-group"><label>Password {{ isset($user) ? '(kosongkan jika tidak diubah)' : '' }}</label><input class="form-control" type="password" name="password" {{ isset($user) ? '' : 'required' }}></div></div><div class="col-md-6"><div class="form-group"><label>Konfirmasi Password</label><input class="form-control" type="password" name="password_confirmation" {{ isset($user) ? '' : 'required' }}></div></div></div><div class="d-flex justify-content-end"><a href="/users" class="btn btn-light me-2">Batal</a><button class="btn btn-primary">{{ $submitLabel }}</button></div>
